function beta_bp_fail(string $msg, int $code = 400): void {
    while (ob_get_level() > 0) { ob_end_clean(); }
    http_response_code($code); header('Content-Type: application/json');
    echo json_encode(['success' => false, 'error' => $msg]); exit();
}
// Global known bots (admin panel, website.known_bots): the bots never award them points, so the beta page flags them.
function beta_bp_known_bots(): array {
    global $conn;
    $out = [];
    try {
        if (!isset($conn) || !$conn) return $out;
        $r = $conn->query('SELECT bot_login FROM known_bots WHERE is_active = 1 ORDER BY bot_login');
        if ($r) { while ($row = $r->fetch_row()) $out[] = strtolower((string) $row[0]); $r->free(); }
    } catch (Throwable $e) { error_log('beta bot-points known_bots: ' . $e->getMessage()); }
    return $out;
}
if (isset($_GET['action']) || (isset($_GET['ajax_action']) && $_GET['ajax_action'] !== 'list')) beta_bp_fail('Unknown action.');
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $bP = fn($k) => (string) ($_POST[$k] ?? '');
    $bUser = function () use ($bP, $db) {
        $u = $bP('user_name');
        if ($u === '' || mb_strlen($u) > 255 || preg_match('/[\x00-\x1F\x7F]/', $u)) beta_bp_fail('Unknown user.');
        $st = $db->prepare('SELECT 1 FROM bot_points WHERE user_name = ? LIMIT 1'); $st->bind_param('s', $u); $st->execute();
        $ok = (bool) $st->get_result()->fetch_row(); $st->close();
        if (!$ok) beta_bp_fail('That user is not in the points list.', 404);
    };
    if (isset($_POST['update_points'])) {
        $bUser();
        if (!preg_match('/^\d{1,10}$/', $bP('points')) || (int) $bP('points') > 2147483647) beta_bp_fail('Points must be a whole number from 0 to 2147483647.');
    } elseif (isset($_POST['remove_user'])) {
        $bUser();
    } elseif (isset($_POST['update_settings'])) {
        $n = trim($bP('point_name'));
        if ($n === '' || mb_strlen($n) > 50 || preg_match('/[\x00-\x1F\x7F<>]/', $n)) beta_bp_fail('Points name must be 1 to 50 characters, without < or >.');
        $_POST['point_name'] = $n;
        foreach (['point_amount_chat' => 'Per chat message', 'point_amount_follower' => 'For following', 'point_amount_subscriber' => 'For subscribing', 'point_amount_cheer' => 'Per cheer', 'point_amount_raid' => 'Per raid viewer'] as $k => $l)
            if (!preg_match('/^\d{1,6}$/', $bP($k)) || (int) $bP($k) > 100000) beta_bp_fail("$l must be a whole number from 0 to 100000.");
        if (!in_array($bP('subscriber_multiplier'), ['0', '2', '3', '4', '5', '6', '7', '8', '9', '10'], true)) beta_bp_fail('Choose a subscriber multiplier.');
        $x = trim($bP('excluded_users'));
        if (mb_strlen($x) > 1000 || !preg_match('/^[A-Za-z0-9_, ]*$/', $x)) beta_bp_fail('Excluded users must be Twitch usernames separated by commas.');
        $_POST['excluded_users'] = implode(',', array_values(array_filter(array_map('trim', explode(',', $x)), 'strlen')));
    } else beta_bp_fail('Unknown action.');
}
// List endpoint first so the browser can paint skeletons, then fetch rows.
// Keep ?action=get_points_data as the existing poll hook (same query, legacy array shape).
$isListAjax = isset($_GET['ajax_action']) && $_GET['ajax_action'] === 'list';
$isLegacyPointsAjax = isset($_GET['action']) && $_GET['action'] == 'get_points_data';
if ($isListAjax || $isLegacyPointsAjax) {
    header('Content-Type: application/json');
    try {
        if (!$db) {
            throw new Exception("Database connection not available");
        }
        $pointsStmt = $db->prepare("SELECT user_name, points FROM bot_points ORDER BY points DESC");
        if (!$pointsStmt) {
            throw new Exception("Prepare failed: " . $db->error);
        }
        if (!$pointsStmt->execute()) {
            throw new Exception("Execute failed: " . $pointsStmt->error);
        }
        $result = $pointsStmt->get_result();
        if (!$result) {
            throw new Exception("Get result failed: " . $pointsStmt->error);
        }
        $pointsData = [];
        while ($row = $result->fetch_assoc()) {
            $pointsData[] = $row;
        }
        $pointsStmt->close();
        if ($isListAjax) {
            echo json_encode(['success' => true, 'points' => $pointsData, 'known_bots' => beta_bp_known_bots()]);
        } else {
            echo json_encode($pointsData);
        }
        exit();
    } catch (Exception $e) {
        error_log("bot_points.php AJAX error: " . $e->getMessage() . "\n" . $e->getTraceAsString());
        http_response_code(500);
        if ($isListAjax) {
            echo json_encode(['success' => false, 'error' => 'Failed to load points data']);
        } else {
            echo json_encode(['error' => 'Failed to load points data']);
        }
        exit();
    }
}

